local mainMod = "SUPER"
local terminal = "alacritty"
local filemanager = "dolphin"
local browser = "brave"
local pdfreader = "okular"
local ebookreader = "foliate"

hl.bind(mainMod .. " + T", hl.dsp.exec_cmd(terminal))
hl.bind("SUPER+SHIFT + T", hl.dsp.exec_cmd("foot"))
hl.bind(mainMod .. " + F", hl.dsp.exec_cmd(filemanager))
hl.bind(mainMod .. " + B", hl.dsp.exec_cmd("DISPLAY=:0 " .. browser .. " --ozone-platform=x11"))
hl.bind(mainMod .. " + O", hl.dsp.exec_cmd(pdfreader))
hl.bind(mainMod .. " + G", hl.dsp.exec_cmd("DISPLAY=:0 GDK_BACKEND=x11 " .. ebookreader))
hl.bind("ALT + Tab", hl.dsp.focus({ workspace = "e+1" }))
hl.bind("ALT+SHIFT + Tab", hl.dsp.focus({ workspace = "e-1" }))
-- TODO: manual review on line 21 — no mapping for dispatcher "workspaceopt"
-- hl.bind(mainMod .. " + I", hl.dsp.workspaceopt("allfloat"))
hl.bind("SUPER+SHIFT + Tab", hl.dsp.window.cycle_next({ next = true }))
hl.bind("ALT + F4", hl.dsp.window.close())
hl.bind("F12", hl.dsp.window.fullscreen({ mode = "fullscreen", action = "toggle" }))
hl.bind(mainMod .. " + N", hl.dsp.focus({ workspace = "empty" }))
hl.bind(mainMod .. " + R", hl.dsp.exec_cmd("hyprctl reload"))
hl.bind(mainMod .. " + V", hl.dsp.window.float({ action = "toggle" }))


-- hl.bind("SUPER+SHIFT + right", hl.dsp.exec_cmd("resizeactive 40 0"))
-- hl.bind("SUPER+SHIFT + left", hl.dsp.exec_cmd("resizeactive -40 0"))
