-- PrtSc: Capture whole screen
hl.bind("Print", hl.dsp.exec_cmd("hyprshot -m output -m eDP-1 -o ~/Pictures"))
-- Super + Shift + PrtSc: HD capture of whole screen
hl.bind("SUPER + SHIFT + Print", hl.dsp.exec_cmd("bash -c 'grim -l 0 -t png - | tee ~/Pictures/$(date +%Y%m%d_%Hh%Mm%Ss)_grim_full.png | wl-copy'"))
-- Super + PrtSc: Capture specific window
hl.bind("SUPER + Print", hl.dsp.exec_cmd("hyprshot -m window -o ~/Pictures"))
-- Ctrl + Shift + PrtSc: HD capture of selected region
hl.bind("CTRL + SHIFT + Print", hl.dsp.exec_cmd("bash -c 'sel=$(slurp -b 00000000 -c 00000000 -s 00000000) && grim -l 0 -t png -g \"$sel\" - | tee ~/Pictures/$(date +%Y%m%d_%Hh%Mm%Ss)_grim_cut.png | wl-copy'"))
-- Shift + PrtSc: Lowres capture of selected region
hl.bind("SHIFT + Print", hl.dsp.exec_cmd("grimblast -f copysave area"))

hl.bind("XF86MonBrightnessUp", hl.dsp.exec_cmd("brightnessctl set 960+"))
hl.bind("XF86MonBrightnessDown", hl.dsp.exec_cmd("brightnessctl set 960-"))
hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("amixer set Master 5%+"))
hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd("amixer set Master 5%-"))
hl.bind("XF86AudioMute", hl.dsp.exec_cmd("amixer set Master toggle"))

hl.bind("XF86AudioPlay", hl.dsp.exec_cmd("playerctl play-pause"))
hl.bind("XF86AudioNext", hl.dsp.exec_cmd("playerctl next"))
hl.bind("XF86AudioPrev", hl.dsp.exec_cmd("playerctl previous"))

hl.bind("ALT + X", hl.dsp.exec_cmd("playerctl play-pause"))
hl.bind("ALT + Z", hl.dsp.exec_cmd("playerctl previous"))
hl.bind("ALT + C", hl.dsp.exec_cmd("playerctl next"))
hl.bind(mainMod .. " + L", hl.dsp.exec_cmd("swaylock"))
hl.bind(mainMod .. " + A", hl.dsp.exec_cmd("rofi -show drun"))
hl.bind(mainMod .. " + E", hl.dsp.exec_cmd("emote"))

-- rofi animation
hl.animation({
    leaf = "layers",
    enabled = true,
    speed = 7,
    bezier = "default",
    style = "slide",
})
hl.bind(mainMod .. " + F8", hl.dsp.exec_cmd("wlsunset -T 5000"))
hl.bind(mainMod .. " + F7", hl.dsp.exec_cmd("pkill wlsunset"))
hl.bind(mainMod .. " + F12", hl.dsp.exec_cmd("wlogout"))

-- Move Windows with mainMod + arrow keys
hl.bind("SUPER + SHIFT + left", hl.dsp.window.move({ direction = "l" }))
hl.bind("SUPER + SHIFT + right", hl.dsp.window.move({ direction = "r" }))
hl.bind("SUPER + SHIFT + up", hl.dsp.window.move({ direction = "u" }))
hl.bind("SUPER + SHIFT + down", hl.dsp.window.move({ direction = "d" }))

-- Move active window to a workspace with mainMod + SHIFT + [0-9]
hl.bind("SUPER + SHIFT + 1", hl.dsp.window.move({ workspace = 1 }))
hl.bind("SUPER + SHIFT + 2", hl.dsp.window.move({ workspace = 2 }))
hl.bind("SUPER + SHIFT + 3", hl.dsp.window.move({ workspace = 3 }))
hl.bind("SUPER + SHIFT + 4", hl.dsp.window.move({ workspace = 4 }))
hl.bind("SUPER + SHIFT + 5", hl.dsp.window.move({ workspace = 5 }))
hl.bind("SUPER + SHIFT + 6", hl.dsp.window.move({ workspace = 6 }))
hl.bind("SUPER + SHIFT + 7", hl.dsp.window.move({ workspace = 7 }))
hl.bind("SUPER + SHIFT + 8", hl.dsp.window.move({ workspace = 8 }))
hl.bind("SUPER + SHIFT + 9", hl.dsp.window.move({ workspace = 9 }))
hl.bind("SUPER + SHIFT + 0", hl.dsp.window.move({ workspace = 10 }))

-- Move/resize windows with mainMod + LMB/RMB and dragging
hl.bind("SUPER + mouse:272", hl.dsp.window.drag())
hl.bind("SUPER + mouse:273", hl.dsp.window.resize())
hl.bind("SUPER + Control_L", hl.dsp.window.drag())
hl.bind("SUPER + ALT_L", hl.dsp.window.resize())

-- Resize Floating window
hl.bind("SUPER + ALT + right", hl.dsp.window.resize({ x = 50, y = 0, relative = true }))
hl.bind("SUPER + ALT + left", hl.dsp.window.resize({ x = -50, y = 0, relative = true }))
hl.bind("SUPER + ALT + up", hl.dsp.window.resize({ x = 0, y = -50, relative = true }))
hl.bind("SUPER + ALT + down", hl.dsp.window.resize({ x = 0, y = 50, relative = true }))

